mapper.update:
UPDATE ${table} SET pool_name = #{w.poolName}, preset_name = #{w.presetName},
                    start_cron = #{w.startCron}, end_cron = #{w.endCron}
WHERE id = #{w.id}

mapper.select:
SELECT id, pool_name, preset_name, start_cron, end_cron
FROM ${table}

    pool_name = #{poolName}

ORDER BY pool_name, id

SELECT id, occurred_at, host, pool_name, preset_name, source,
       old_core, old_max, old_keep, new_core, new_max, new_keep, old_queue, new_queue
FROM ${table} ORDER BY occurred_at DESC, id DESC LIMIT #{limit}
